WITH supplier_stats AS (SELECT supplier_id, COUNT(stock_qty) AS stock_qty_count, COUNT(DISTINCT stock_qty) AS unique_brands FROM products WHERE product_name NOT LIKE 'Y%' GROUP BY supplier_id) SELECT s.id, s.supplier_name, s.country, ss.stock_qty_count, ss.unique_brands FROM suppliers s INNER JOIN supplier_stats ss ON s.id = ss.supplier_id WHERE ss.stock_qty_count > 3 ORDER BY country DESC, id LIMIT 10
